public final class Person {
    private final List<Course> courses = new ArrayList<>();
    private final List<Course> view = Collections.unmodifiableList(courses);

    public List<Course> courses() { return view; }            // live, read-only
    public void addCourse(Course c) { requireAccepted(c); courses.add(c); }
    public void removeCourse(Course c) { courses.remove(c); }
}

